"""Reviewed Japanese national history, contemporary economic records and 2020 statistics."""
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from records import source, evidence, event, context, save_batch
from japan_sources import repository_for, polish_records

events, contexts = [], []
def doc(key, title, url, date, ident, locator, primary=False, typ='government_document', lang='en', kind='government'):
    repo=source('JP',key,title,url,lang,publisher=repository_for(url), kind=kind, accessed_on='2026-11-17',notes='Прочитано: '+locator+'. Современный очерк не считается первичным только из-за архивного домена. Собственный пересказ, без изображений и заимствованного текста.')
    return evidence(repo,title,ident,date,lang,typ if primary else 'historical_study',locator,primary=primary,locator=locator)
def add(ev,slug,date,ru,en,text,english,category,sensitive=False):
    row=event('JP',slug,date,'jp',ru,en,text,english,ev,category=category,scope='national',sensitive=sensitive)
    if not ev['is_primary']: row['confidence']='medium'
    events.append(row); return row
def ctx(ev,slug,first,last,kind,ru,en,text,english,statistics=None):
    contexts.append(context('JP',slug,'jp',first,last,kind,ru,en,text,english,ev,statistics))

# Each essay was opened and read. Its uninspected linked originals are not primary evidence.
for slug,date,chapter,number,title,ru,en,summary,english,category,sensitive in [
 ('1904-russo-japanese-war','1904-02-10',2,26,'Russo-Japanese War','Русско-японская война','Russo-Japanese War','Япония объявила войну России после начала военных действий в феврале1904 года. Военные операции шли в том числе в Корее и Маньчжурии; личное участие семьи не предполагается.','Japan declared war on Russia after hostilities began in February1904. Operations included Korea and Manchuria; family involvement is not presumed.','war_conflict',True),
 ('1910-korea-annexation','1910-08-22',2,27,"Japan’s Annexation of Korea",'Договор об аннексии Кореи','Treaty annexing Korea','Был подписан договор об аннексии Кореи Японией. Это этап колониальной экспансии, а не мирное добровольное объединение населения.','A treaty annexing Korea to Japan was signed, a stage of colonial expansion rather than a voluntary union of populations.','political_change',True),
 ('1918-rice-riots','1918-07',3,6,'Rice Riots','Рисовые бунты','Rice riots','Протесты против дороговизны риса начались в Тояма и распространились по стране. Участие конкретной женщины и нехватка еды в её семье не выводятся из общего события.','Protests against rice prices began in Toyama and spread across the country. Personal participation or a particular family’s food shortage is not presumed.','economic_crisis',True),
 ('1925-peace-preservation-law','1925',3,13,'Universal Manhood Suffrage and Peace Preservation Law','Закон об охране общественного порядка','Peace Preservation Law','Одновременно с расширением мужского голосования был принят репрессивный закон об охране общественного порядка. Новые избирательные возможности сосуществовали с ограничениями политической деятельности.','Expanded male voting coexisted with the repressive Peace Preservation Law and restrictions on political activity.','repression',True),
 ('1931-manchurian-invasion','1931-09-18',4,1,'Manchurian Incident of1931','Захват Маньчжурии','Invasion of Manchuria','Взрыв, устроенный офицерами Квантунской армии у Мукдена, стал поводом для военного захвата Маньчжурии. Увеличение влияния военных меняло политику страны.','A railway explosion arranged by Kwantung Army officers near Mukden became a pretext for invading Manchuria, as military influence grew.','war_conflict',True),
 ('1945-atomic-bombings','1945-08-06',4,21,'Deterioration of War Situation','Атомные бомбардировки Хиросимы и Нагасаки','Atomic bombings of Hiroshima and Nagasaki','США сбросили атомную бомбу на Хиросиму6 августа, на Нагасаки9 августа. Национальная историческая веха не устанавливает местонахождение, ранения или статус хибакуся у героини.','The United States dropped atomic bombs on Hiroshima on August6 and Nagasaki on August9. This national milestone establishes neither the character’s presence nor injuries or hibakusha status.','war_conflict',True),
 ('1952-occupation-ends','1952-04-28',5,14,'Peace Treaty and the U.S.-Japan Security Treaty','Окончание союзной оккупации','Allied occupation ends','Вступление в силу Сан-Францисского мирного договора завершило союзную оккупацию основной территории Японии. Окинава оставалась под американским управлением до1972 года.','The San Francisco Peace Treaty ended the Allied occupation of Japan proper. Okinawa remained under US administration until1972.','political_change',False),
 ('1955-ldp-formation','1955-11-15',6,7,'Unification of Conservative Parties','Создание Либерально-демократической партии','Liberal Democratic Party formed','Объединение двух консервативных партий создало ЛДП и стало важной частью политического порядка1955 года. Партийные взгляды семьи не назначаются.','Two conservative parties merged into the LDP, a major element of the1955 political system. The family is not assigned party views.','political_change',False),
]:
    ev=doc('jp_ndl_history_'+slug,title,'https://www.ndl.go.jp/modern/e/cha'+str(chapter)+'/description'+str(number).zfill(2)+'.html','2006–2010; exhibition copyright dates','NDL Modern Japan '+str(chapter)+'-'+str(number),'Историческое объяснение соответствующего события; связанные сканы не засчитаны.',kind='library')
    row=add(ev,slug,date,ru,en,summary,english,category,sensitive)
    if slug=='1945-atomic-bombings': row['end_date']='1945-08-09'

chron=doc('jp_ndl_chronology_reviewed','Modern Japan: Chronological Table','https://www.ndl.go.jp/modern/e/utility/chronology.html','2006–2010; exhibition copyright dates','NDL chronology','Строка23.08.1914: объявление войны Германии; современная хронология, не первоисточник.',kind='library')
add(chron,'1914-first-world-war','1914-08-23','Вступление в Первую мировую войну','Japan enters World WarI','Япония объявила войну Германии и вступила в Первую мировую войну на стороне союзников. Это внешнеполитический фон жизни, а не доказательство фронтового опыта семьи.','Japan declared war on Germany and entered World WarI on the Allied side. This establishes national context, not a family member’s military service.','war_conflict',True)
census=doc('jp_census_history','国勢調査のあゆみ','https://www.stat.go.jp/data/kokusei/2015/kouhou/ayumi.html','2015 public census information; exact page date unstated','Statistics Bureau/census history','Раздел1920: первая национальная перепись; историческое объяснение, не оригинальные листы1920.',lang='ja',kind='statistics')
add(census,'1920-first-census','1920','Первая общенациональная перепись','First national population census','Состоялась первая общенациональная перепись населения Японии. Исторический охват и тогдашние границы следует отличать от современной территории и от муниципальных рядов.','Japan held its first national population census. Its historical scope and boundaries differ from modern territory and municipal series.','everyday_life')
health=doc('jp_social_security_history','White Paper: Social Security’s Development History','https://www.mhlw.go.jp/www1/english/wp_5/vol1/p1c1s1.html','1999 (survey and reporting context)','White Paper vol1,p1c1s1','Раздел implementation of universal insurance: муниципальная система с апреля1961; ретроспективный очерк для этого события.')
add(health,'1961-universal-insurance','1961-04','Всеобщие системы медицинского и пенсионного страхования','Universal health and pension insurance systems','Муниципальные службы национального медицинского страхования действовали по всей стране; была развёрнута и национальная пенсионная система. Условия и размеры помощи оставались различными.','National Health Insurance services operated across municipalities and the national pension system was rolled out. Conditions and benefits still varied.','social_policy')
ctx(health,'1961-medical-access',1961,1969,'healthcare','Страхование и медицинская помощь','Insurance and medical care','Расширение страхования уменьшало правовой разрыв охвата между работниками предприятий и другими группами. Оно не означает бесплатности любого лечения или одинакового доступа во всех районах.','Wider insurance reduced gaps between employees and other groups. It did not make every treatment free or access equal everywhere.')
ctx(health,'1955-urban-work-migration',1955,1964,'migration','Рост городов и перемещение труда','Urban growth and movement of labour','Ретроспективный государственный обзор описывает переход от сельского хозяйства к промышленности и приток в крупные города. Это национальная тенденция, не местная вероятность переезда.','The government review describes movement from agriculture into industry and metropolitan areas. This is a national trend, not a precise local migration probability.')

for key,title,url,slug,date,ru,en,text,english,category in [
 ('jp_wiki_china_war','Second Sino-Japanese War','https://en.wikipedia.org/wiki/Second_Sino-Japanese_War','1937-war-in-china','1937-07-07','Полномасштабная война в Китае','Full-scale war in China','После столкновения у моста Лугоуцяо война расширилась до полномасштабного японского вторжения в Китай. Запись не оправдывает насилие и не приписывает гражданскому персонажу участие в нём.','Fighting near the Marco Polo Bridge escalated into full-scale Japanese invasion of China. Civilian characters are not assigned participation in the violence.','war_conflict'),
 ('jp_wiki_olympics1964','1964 Summer Olympics','https://en.wikipedia.org/wiki/1964_Summer_Olympics','1964-olympics','1964-10-10','Олимпийские игры1964 года','1964 Olympic Games','В Токио начались первые летние Олимпийские игры в Азии. Национальная веха не означает посещения соревнований героиней.','Tokyo hosted the first Summer Olympics in Asia. The national milestone does not establish the character’s attendance.','sport'),
 ('jp_wiki_shinkansen','Tokaido Shinkansen','https://en.wikipedia.org/wiki/T%C5%8Dkaid%C5%8D_Shinkansen','1964-shinkansen','1964-10-01','Открытие Токайдо-синкансэн','Tokaido Shinkansen opens','Скоростная линия соединила Токио и Син-Осаку через Киото. Расширение транспортных возможностей не означает, что поездка стала доступной каждой семье.','The high-speed railway linked Tokyo and Shin-Osaka via Kyoto. Expanded transport did not make a journey affordable for every family.','infrastructure_transport'),
 ('jp_wiki_asset_bubble','Japanese asset price bubble','https://en.wikipedia.org/wiki/Japanese_asset_price_bubble','1992-bubble-collapse','1992','Последствия краха финансового пузыря','After the asset bubble collapsed','После падения цен на акции и землю экономика вошла в длительный период трудностей. Последствия различались по месту и положению семьи; разорение героине не назначается.','Falling share and land prices ushered in prolonged economic difficulties, with uneven effects by location and household. Personal ruin is not automatic.','economic_crisis'),
 ('jp_wiki_covid2020','COVID-19 pandemic in Japan','https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Japan','2020-pandemic-emergency','2020-04-07','Пандемия и режим чрезвычайной ситуации','Pandemic state of emergency','Правительство объявило режим чрезвычайной ситуации сначала в семи префектурах,16 апреля расширило его на страну. Это не одинаковый опыт болезни, потерь или ограничений у каждого человека.','The government declared an emergency in seven prefectures, extending it nationwide on April16. Illness, losses and restrictions were not identical for everyone.','public_health'),
]:
    ev=doc(key,title,url,'undated current revision; accessed2026-11-17',title+'; introductory/history sections','Прочитаны конкретная дата и описание события; вторичный источник по разрешению владельца.',kind='encyclopedia')
    add(ev,slug,date,ru,en,text,english,category,category in {'war_conflict','public_health'})

