oil=doc('jp_bluebook_1974_oil','Diplomatic Bluebook1974,Chapter1','https://www.mofa.go.jp/policy/other/bluebook/1974/1974-1.htm','1974 reporting year; exact publication date not established','Diplomatic Bluebook1974,Chapter1§1','Contemporary ministry report: autumn1973 oil production cuts/price rises and inflationary slowdown; official perspective is attributed.',True,typ='administrative_report')
add(oil,'1973-oil-crisis','1973','Нефтяной кризис','Oil crisis','Рост нефтяных цен и ограничения поставок вызвали инфляцию и серьёзное замедление экономики. Современный кризису отчёт МИД фиксировал общий международный фон; точные местные цены не выводятся.','Oil prices and supply restrictions drove inflation and economic slowdown. The contemporary foreign ministry report documents the international setting, not precise local prices.','economic_crisis')

for key,title,url,date,slug,ru,en,text,english in [
 ('jp_boj_1997_yamaichi','Statement by the Governor','https://www.boj.or.jp/en/about/press/danwa/dan9711c.htm','1997-11-24','1997-financial-instability','Финансовая нестабильность1997 года','Financial instability in1997','На фоне череды финансовых проблем Yamaichi Securities сообщила о прекращении операций. Банк Японии объявил меры ликвидности; это не означает потери вкладов каждым жителем.','Amid financial instability, Yamaichi Securities announced suspension of operations. The Bank of Japan provided liquidity measures; losses by every resident are not implied.'),
 ('jp_boj_2001_easing','New Procedures for Money Market Operations and Monetary Easing','https://www.boj.or.jp/en/mopo/mpmdeci/mpr_2001/k010319a.htm','2001-03-19','2001-quantitative-easing','Новая политика против дефляции','New policy against deflation','Банк Японии перешёл к новой схеме количественного смягчения на фоне слабого спроса и давления на цены. Это решение, а не доказательство быстрого восстановления доходов.','The Bank of Japan changed to quantitative easing amid weak demand and downward price pressure. This was a policy decision, not proof of rapid income recovery.'),
 ('jp_boj_2008_crisis','On Monetary Policy Decisions','https://www.boj.or.jp/en/mopo/mpmdeci/mpr_2008/k081219.pdf','2008-12-19','2008-global-financial-crisis','Мировой финансовый кризис в Японии','Global financial crisis in Japan','Банк Японии снизил целевую краткосрочную ставку примерно до0.1% и сообщил об ухудшении экспорта, занятости и доходов. Условия отдельной семьи могли отличаться.','The Bank of Japan cut its short-term target to around0.1% and reported weaker exports, employment and income. Individual households could differ.'),
 ('jp_boj_2013_qqe','Introduction of Quantitative and Qualitative Monetary Easing','https://www.boj.or.jp/en/mopo/mpmdeci/mpr_2013/k130404a.pdf','2013-04-04','2013-monetary-easing','Новая программа денежного смягчения','New monetary easing programme','Банк Японии объявил масштабное количественное и качественное смягчение с целью изменения инфляционной динамики. Заявленные цели не записываются как уже достигнутые результаты.','The Bank of Japan announced large-scale quantitative and qualitative easing to change inflation dynamics. Targets are not recorded as achieved results.'),
]:
    ev=doc(key,title,url,date,'Bank of Japan/'+date,'Оригинальное датированное заявление; вводные разделы и решение. Прогнозы отделены от результатов.',True,typ='government_document')
    add(ev,slug,date,ru,en,text,english,'economic_crisis')
    if '2008' in key:
        ctx(ev,'2008-employment-income',2008,2008,'wages_income','Занятость и доходы во время кризиса','Employment and income in the crisis','Банк Японии сообщил об ухудшении общей ситуации занятости и доходов. Документ не даёт городскую зарплату и не доказывает увольнение героини.','The Bank reported worsening employment and household income conditions. It provides neither a city wage nor proof that the character lost her job.')
jma=doc('jp_jma_earthquake2011','The2011 Great East Japan Earthquake,first report','https://www.jma.go.jp/jma/en/News/2011_Earthquake_01.html','2011 (rapid report,precise release date unstated)','JMA first report/Earthquake Summary','Датированное наблюдение11.03.2011,14:46JST; магнитуда9.0 interim, цунами. Авария АЭС не подтверждается одним сейсмическим отчётом.',True,typ='government_document')
add(jma,'2011-tohoku-earthquake','2011-03-11','Землетрясение и цунами на северо-востоке Японии','Northeastern earthquake and tsunami','Мощное землетрясение у побережья Тохоку вызвало разрушительное цунами. Общенациональная веха не переносит разрушения Тохоку в каждый поддержанный город и не назначает семье потери.','A powerful earthquake off Tohoku caused a devastating tsunami. A national milestone does not move the destruction to every supported city or assign family losses.','disaster',True)
